// friday13.cs — Find earliest Friday the 13th and count them in a 400-year cycle
// using the proleptic Gregorian calendar.

// Find the earliest Friday the 13th starting from 0001-01-01
DateOnly date = new DateOnly(1, 1, 13); // start checking the 13th of each month
DateOnly earliest = default;

for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            if (earliest == default)
            {
                earliest = d;
            }
        }
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");

// Count all Friday the 13ths in a full 400-year Gregorian cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateOnly(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: distribution by month
var byMonth = Enumerable.Range(1, 12)
    .Select(m => (Month: m, Count: Enumerable.Range(1, 400)
        .Count(y => new DateOnly(y, m, 13).DayOfWeek == DayOfWeek.Friday)))
    .ToList();

Console.WriteLine("\nDistribution by month:");
foreach (var (month, c) in byMonth)
    Console.WriteLine($"  {new DateOnly(2000, month, 1):MMMM,-12} {c}");

